    jid = "%s.%d" % (sys.argv[1], os.getpid())
    time_limit = sys.argv[2]
    wrapped_module = sys.argv[3]
    argsfile = sys.argv[4]
    if '-tmp-' not in os.path.dirname(wrapped_module):
        preserve_tmp = True
    elif len(sys.argv) > 5:
        preserve_tmp = sys.argv[5] == '-preserve_tmp'
    else:
        preserve_tmp = False
    try:
        time_limit = int(time_limit)
        if time_limit < 0:
            raise ValueError('time limit must be non-negative')
    except ValueError as e:
        _cleanup_tmp(wrapped_module, preserve_tmp)
        end(_failure(jid, 'invalid time limit: %s' % to_text(e),
