                    os.setpgid(sub_pid, sub_pid)
                    deadline = time.time() + time_limit
                    notice("Start watching %s (%s)" % (sub_pid, time_limit))
                    while os.waitpid(sub_pid, os.WNOHANG) == (0, 0):
